<?php require_once 'includes/functions.php';$u=login_required('donor');if($_SERVER['REQUEST_METHOD']!=='POST')go('dashboard.php');check_csrf();$id=(int)($_POST['id']??0);$act=$_POST['action']??'';$s=db()->prepare('SELECT * FROM blood_requests WHERE request_id=? AND donor_id=?');$s->execute([$id,$u['user_id']]);$r=$s->fetch();if(!$r){flash('Request not found.','error');go('dashboard.php');}if(in_array($act,['accept','reject'])&&$r['status']==='Pending'){$st=$act==='accept'?'Accepted':'Rejected';db()->prepare('UPDATE blood_requests SET status=? WHERE request_id=?')->execute([$st,$id]);notice((int)$r['patient_id'],'Request #'.$id.' was '.$st,'request');flash('Request '.$st.'.');}elseif($act==='donated'&&$r['status']==='Accepted'){$code=(string)random_int(100000,999999);$p=db();$p->beginTransaction();try{$p->prepare("UPDATE blood_requests SET status='Donation_Marked' WHERE request_id=?")->execute([$id]);$p->prepare("INSERT INTO donations(request_id,donor_id,patient_id,status,donation_date) VALUES(?,?,?,'Marked',NOW()) ON DUPLICATE KEY UPDATE status='Marked',donation_date=NOW()")->execute([$id,$u['user_id'],$r['patient_id']]);$p->prepare("INSERT INTO verification_codes(request_id,code_hash,expires_at,status) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 30 MINUTE),'Active') ON DUPLICATE KEY UPDATE code_hash=VALUES(code_hash),expires_at=VALUES(expires_at),status='Active'")->execute([$id,password_hash($code,PASSWORD_DEFAULT)]);$p->commit();notice((int)$r['patient_id'],'Donation marked for request #'.$id.'. Ask the donor for the verification code.','donation');flash('Donation marked. Give the patient this code: '.$code.' (30-minute expiry).');}catch(Throwable $e){$p->rollBack();flash('Could not update donation.','error');}}else flash('Invalid action or request status.','error');go('dashboard.php');?>